"""Tests for the update command (design §9)."""

import contextlib
import io
import json
import subprocess
import tempfile
import unittest
from pathlib import Path
from unittest import mock

from agent_kit import installer
from tests.guardrail.support import (
    FakeStdin,
    GitRepo,
    block_content,
    copied_payload,
    lock_data,
    read_text,
    sha256_file,
    sha256_text,
)

BEGIN = "<!-- agent-kit:begin -->"
END = "<!-- agent-kit:end -->"
HARNESS_SH = (
    "# Generated by agent-kit. Do not edit; run `agent-kit update` instead.\n"
    'AGENT_MARKERS="AI_AGENT OPENCODE"\n'
)
LOCK = ".agents/kit.lock"


def expected_files(payload):
    expected = {}
    for folder, prefix in (
        (payload / "kit", ".agents/kit/"),
        (payload / "skills", ".agents/skills/"),
    ):
        for source in sorted(folder.rglob("*")):
            if source.is_file():
                expected[prefix + source.relative_to(folder).as_posix()] = (
                    sha256_file(source)
                )
    expected[".agents/kit/harness.sh"] = sha256_text(HARNESS_SH)
    return expected


def snapshot(root):
    """Every file under root except .git, by repo-relative POSIX path."""
    result = {}
    for path in Path(root).rglob("*"):
        if not path.is_file():
            continue
        relative = path.relative_to(root)
        if relative.parts[0] == ".git":
            continue
        result[relative.as_posix()] = path.read_bytes()
    return result


class UpdateTests(unittest.TestCase):
    def setUp(self):
        self.repo = GitRepo()
        self.addCleanup(self.repo.close)
        self.root = self.repo.root
        self.install()

    def call_init(self, payload=None):
        stdout = io.StringIO()
        stderr = io.StringIO()
        with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
            code = installer.init(
                self.root,
                None,
                False,
                FakeStdin(),
                stdout,
                payload=payload,
            )
        return code, stdout.getvalue(), stderr.getvalue()

    def install(self):
        code, stdout, stderr = self.call_init()
        self.assertEqual(code, 0, stdout + stderr)
        return stdout

    def run_update(self, force=False, stdin=None, payload=None, version=None):
        stdout = io.StringIO()
        stderr = io.StringIO()
        with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
            if version is None:
                code = installer.update(
                    self.root, force, stdin or FakeStdin(), stdout, payload=payload
                )
            else:
                with mock.patch.object(installer, "__version__", version):
                    code = installer.update(
                        self.root,
                        force,
                        stdin or FakeStdin(),
                        stdout,
                        payload=payload,
                    )
        return code, stdout.getvalue(), stderr.getvalue()

    def newer_payload(self):
        """A payload with one file changed, one added and one removed."""
        payload = copied_payload(self)
        changed = payload / "kit" / "workflow.md"
        changed.write_bytes(changed.read_bytes() + b"\nNew rule.\n")
        (payload / "kit" / "new-file.txt").write_bytes(b"new\n")
        (payload / "kit" / "triage-labels.md").unlink()
        block = payload / "agents-block.md"
        block.write_bytes(block.read_bytes() + b"\nA new kit line.\n")
        return payload

    def assert_unchanged(self, before):
        self.assertEqual(snapshot(self.root), before)

    # -- the happy path ---------------------------------------------------

    def test_no_local_changes_updates_the_kit(self):
        payload = self.newer_payload()

        code, stdout, stderr = self.run_update(payload=payload, version="0.2.0")

        self.assertEqual(code, 0, stdout + stderr)
        self.assertEqual(stderr, "")
        self.assertEqual(
            (self.root / ".agents/kit/workflow.md").read_bytes(),
            (payload / "kit/workflow.md").read_bytes(),
        )
        self.assertTrue((self.root / ".agents/kit/new-file.txt").is_file())
        self.assertFalse((self.root / ".agents/kit/triage-labels.md").exists())

        data = lock_data(self.root)
        self.assertEqual(data["kit_version"], "0.2.0")
        self.assertEqual(data["files"], expected_files(payload))
        self.assertEqual(
            data["agents_block"], sha256_text(block_content(payload) + "\n")
        )

        self.assertIn("Updated agent-kit from 0.1.0 to 0.2.0.", stdout)
        self.assertIn("Updated:\n  .agents/kit/workflow.md", stdout)
        self.assertIn("Added:\n  .agents/kit/new-file.txt", stdout)
        self.assertIn("Removed:\n  .agents/kit/triage-labels.md", stdout)

    def test_project_owned_files_are_byte_identical_after_an_update(self):
        glossary = self.repo.write("GLOSSARY.md", b"# Mine\n\nA project term.\n")
        project = self.repo.write("docs/agents/project.md", b"# Mine\n\nRules.\n")
        local = self.repo.write(
            ".agents/hooks.local/pre-commit", b"#!/bin/sh\necho local\n"
        )
        agents = read_text(self.root / "AGENTS.md")
        agents_path = self.repo.write(
            "AGENTS.md", "# Project\n\nMine.\n\n" + agents
        )
        outside = agents[agents.index(END) :]

        payload = self.newer_payload()
        code, stdout, stderr = self.run_update(payload=payload, version="0.2.0")

        self.assertEqual(code, 0, stdout + stderr)
        self.assertEqual(glossary.read_bytes(), b"# Mine\n\nA project term.\n")
        self.assertEqual(project.read_bytes(), b"# Mine\n\nRules.\n")
        self.assertEqual(local.read_bytes(), b"#!/bin/sh\necho local\n")
        updated = agents_path.read_text("utf-8")
        self.assertTrue(updated.startswith("# Project\n\nMine.\n\n" + BEGIN + "\n"))
        self.assertTrue(updated.endswith(outside))
        self.assertIn(
            "{}\n{}\n{}".format(BEGIN, block_content(payload), END), updated
        )

    def test_templates_are_not_recreated_by_an_update(self):
        (self.root / "GLOSSARY.md").unlink()

        code, stdout, stderr = self.run_update()

        self.assertEqual(code, 0, stdout + stderr)
        self.assertFalse((self.root / "GLOSSARY.md").exists())

    def test_core_hooks_path_is_reset_to_the_kit(self):
        self.repo.git("config", "core.hooksPath", "somewhere-else")

        code, stdout, stderr = self.run_update()

        self.assertEqual(code, 0, stdout + stderr)
        result = subprocess.run(
            ["git", "-C", str(self.root), "config", "core.hooksPath"],
            capture_output=True,
            text=True,
        )
        self.assertEqual(result.stdout.strip(), ".agents/kit/hooks")

    # -- usage errors -----------------------------------------------------

    def test_a_missing_lock_is_a_usage_error(self):
        (self.root / LOCK).unlink()
        before = snapshot(self.root)

        code, _, stderr = self.run_update()

        self.assertEqual(code, 2)
        self.assertIn("agent-kit is not installed here", stderr)
        self.assertIn("agent-kit init", stderr)
        self.assert_unchanged(before)

    def test_an_invalid_lock_is_a_usage_error(self):
        (self.root / LOCK).write_text("not json", encoding="utf-8")
        before = snapshot(self.root)

        code, _, stderr = self.run_update()

        self.assertEqual(code, 2)
        self.assertIn("agent-kit is not installed here", stderr)
        self.assert_unchanged(before)

    def test_an_unknown_harness_in_the_lock_is_a_usage_error(self):
        data = lock_data(self.root)
        data["harness"] = "claude"
        (self.root / LOCK).write_text(json.dumps(data), encoding="utf-8")
        before = snapshot(self.root)

        code, _, stderr = self.run_update()

        self.assertEqual(code, 2)
        self.assertIn("claude", stderr)
        self.assertIn("opencode", stderr)
        self.assert_unchanged(before)

    def test_a_plain_folder_is_a_usage_error(self):
        with tempfile.TemporaryDirectory() as folder:
            stdout = io.StringIO()
            stderr = io.StringIO()
            with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(
                stderr
            ):
                code = installer.update(folder, False, FakeStdin(), stdout)

            self.assertEqual(code, 2)
            self.assertIn("not the root of a git repository", stderr.getvalue())

    # -- local changes ----------------------------------------------------

    def test_a_modified_kit_file_is_refused_and_listed(self):
        path = self.root / ".agents/kit/workflow.md"
        path.write_bytes(path.read_bytes() + b"x")
        before = snapshot(self.root)

        code, stdout, _ = self.run_update()

        self.assertEqual(code, 1)
        self.assertIn("Cannot update", stdout)
        self.assertIn(".agents/kit/workflow.md", stdout)
        self.assertIn("modified", stdout)
        self.assert_unchanged(before)

    def test_a_deleted_kit_file_is_refused_and_listed_as_missing(self):
        (self.root / ".agents/kit/workflow.md").unlink()
        before = snapshot(self.root)

        code, stdout, _ = self.run_update()

        self.assertEqual(code, 1)
        self.assertIn(".agents/kit/workflow.md", stdout)
        self.assertIn("missing", stdout)
        self.assert_unchanged(before)

    def test_an_extra_kit_file_is_refused_and_listed(self):
        extra = self.repo.write(".agents/skills/demo/SKILL.md", b"mine\n")
        before = snapshot(self.root)

        code, stdout, _ = self.run_update()

        self.assertEqual(code, 1)
        self.assertIn(".agents/skills/demo/SKILL.md", stdout)
        self.assertIn("not installed by agent-kit", stdout)
        self.assertEqual(extra.read_bytes(), b"mine\n")
        self.assert_unchanged(before)

    def test_an_extra_file_under_the_kit_folder_is_refused(self):
        self.repo.write(".agents/kit/extra.txt", b"mine\n")

        code, stdout, _ = self.run_update()

        self.assertEqual(code, 1)
        self.assertIn(".agents/kit/extra.txt", stdout)
        self.assertIn("not installed by agent-kit", stdout)

    def test_an_edited_kit_block_is_refused_and_listed(self):
        path = self.root / "AGENTS.md"
        text = path.read_text("utf-8").replace(BEGIN + "\n", BEGIN + "\nedited\n", 1)
        path.write_text(text, encoding="utf-8")
        before = snapshot(self.root)

        code, stdout, _ = self.run_update()

        self.assertEqual(code, 1)
        self.assertIn("AGENTS.md", stdout)
        self.assertIn("kit block", stdout)
        self.assert_unchanged(before)

    def test_missing_markers_are_refused_and_listed(self):
        self.repo.write("AGENTS.md", "project text only\n")

        code, stdout, _ = self.run_update()

        self.assertEqual(code, 1)
        self.assertIn("AGENTS.md", stdout)
        self.assertIn("missing markers", stdout)

    def test_a_line_ending_change_only_is_not_a_local_change(self):
        path = self.root / ".agents/kit/workflow.md"
        path.write_bytes(path.read_bytes().replace(b"\n", b"\r\n"))

        code, stdout, stderr = self.run_update()

        self.assertEqual(code, 0, stdout + stderr)

    def test_a_bad_marker_state_is_refused_and_nothing_changes(self):
        path = self.root / "AGENTS.md"
        text = path.read_text("utf-8").replace(END, "", 1)
        path.write_text(text, encoding="utf-8")
        before = snapshot(self.root)

        code, stdout, _ = self.run_update()

        self.assertEqual(code, 1)
        self.assertIn("AGENTS.md", stdout)
        self.assertIn("broken agent-kit block", stdout)
        self.assert_unchanged(before)

    # -- --force ----------------------------------------------------------

    def test_force_without_a_terminal_is_refused_and_nothing_changes(self):
        path = self.root / ".agents/kit/workflow.md"
        path.write_bytes(path.read_bytes() + b"local edit\n")
        before = snapshot(self.root)

        code, stdout, _ = self.run_update(
            force=True, stdin=FakeStdin("yes\n", tty=False)
        )

        self.assertEqual(code, 1)
        self.assertIn("Refusing --force", stdout)
        self.assert_unchanged(before)

    def test_force_with_a_declined_confirmation_changes_nothing(self):
        path = self.root / ".agents/kit/workflow.md"
        path.write_bytes(path.read_bytes() + b"local edit\n")
        before = snapshot(self.root)

        code, stdout, _ = self.run_update(
            force=True, stdin=FakeStdin("no\n", tty=True)
        )

        self.assertEqual(code, 1)
        self.assertIn("These paths will be deleted:", stdout)
        self.assertIn(".agents/kit/workflow.md", stdout)
        self.assertIn("Aborted. Nothing was changed.", stdout)
        self.assert_unchanged(before)

    def test_force_with_yes_discards_local_edits_and_updates(self):
        path = self.root / ".agents/kit/workflow.md"
        path.write_bytes(path.read_bytes() + b"local edit\n")
        payload = self.newer_payload()

        code, stdout, stderr = self.run_update(
            force=True,
            stdin=FakeStdin("yes\n", tty=True),
            payload=payload,
            version="0.2.0",
        )

        self.assertEqual(code, 0, stdout + stderr)
        self.assertNotIn(b"local edit", path.read_bytes())
        self.assertEqual(path.read_bytes(), (payload / "kit/workflow.md").read_bytes())
        self.assertEqual(lock_data(self.root)["kit_version"], "0.2.0")
        self.assertIn("Updated agent-kit from 0.1.0 to 0.2.0.", stdout)


if __name__ == "__main__":
    unittest.main()
